DO $write_guard$
DECLARE
 v_before text := 'ARRAY[''github.issue.comment.create''::text, ''github.issue.comment.update''::text, ''github.pull_request.create''::text, ''github.pull_request.update''::text, ''github.pull_request.review.create''::text]';
 v_after text := 'ARRAY[''github.issue.comment.create''::text, ''github.issue.comment.update''::text, ''github.pull_request.create''::text, ''github.pull_request.update''::text, ''github.pull_request.review.create''::text, ''github.issue.create''::text, ''github.issue.update''::text, ''github.repository.content.create''::text, ''github.repository.content.update''::text, ''github.pull_request.comment.create''::text, ''github.pull_request.comment.update''::text, ''github.pull_request.ready''::text]';
 v_definition text;
BEGIN
 SELECT pg_get_constraintdef(oid) INTO STRICT v_definition FROM pg_constraint
 WHERE conrelid='control_plane.integration_invocations'::regclass AND conname='integration_invocations_approval_check';
 IF md5(v_definition)<>'87f6bc2dd7ef67bf3685d20f753fb474'
 OR (length(v_definition)-length(replace(v_definition,v_before,'')))/length(v_before)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='control_plane.protect_email_mailbox_gate()'::regprocedure
   AND md5(prosrc)='2f240b237995bcbb71eb7a5888db344f' AND pg_get_userbyid(proowner)='control_plane_owner' AND NOT prosecdef)
 THEN RAISE EXCEPTION 'GitHub autonomous write predecessor changed'; END IF;
 ALTER TABLE control_plane.integration_invocations DROP CONSTRAINT integration_invocations_approval_check;
 EXECUTE 'ALTER TABLE control_plane.integration_invocations ADD CONSTRAINT integration_invocations_approval_check ' || replace(v_definition,v_before,v_after);
END $write_guard$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION control_plane.protect_email_mailbox_gate() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP='UPDATE' AND (NEW.mailbox_gate_required IS DISTINCT FROM OLD.mailbox_gate_required
        OR NEW.approval_policy IS DISTINCT FROM OLD.approval_policy
        OR NEW.grant_version IS DISTINCT FROM OLD.grant_version
        OR NEW.approval_scope_paths IS DISTINCT FROM OLD.approval_scope_paths) THEN
        RAISE EXCEPTION 'integration approval binding is immutable';
    END IF;
    IF NEW.mailbox_gate_required OR (NEW.risk<>'READ' AND NEW.approval_policy='NONE' AND NEW.resource_kind='EMAIL_SENDER') THEN
        IF NOT EXISTS (SELECT 1 FROM control_plane.integration_connections c
                       WHERE c.id=NEW.connection_id AND c.organization_id=NEW.organization_id AND c.definition_key='email') THEN
            RAISE EXCEPTION 'mailbox approval requires email owner connection';
        END IF;
    ELSIF NEW.risk<>'READ' AND NEW.approval_policy='NONE' THEN
        IF NEW.risk<>'WRITE' OR NEW.resource_kind<>'GITHUB_REPOSITORY' OR NEW.operation<>NEW.capability_key OR
           NEW.operation NOT IN ('github.issue.comment.create','github.issue.comment.update','github.pull_request.create','github.pull_request.update','github.pull_request.review.create','github.issue.create','github.issue.update','github.repository.content.create','github.repository.content.update','github.pull_request.comment.create','github.pull_request.comment.update','github.pull_request.ready') OR
           NOT EXISTS (SELECT 1 FROM control_plane.integration_connections c
                       WHERE c.id=NEW.connection_id AND c.organization_id=NEW.organization_id AND c.definition_key='github') OR
           (NEW.operation='github.pull_request.review.create' AND NEW.bounded_input->>'event' IS DISTINCT FROM 'COMMENT') THEN
            RAISE EXCEPTION 'autonomous integration write is not allowed';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
-- +goose StatementEnd
RESET ROLE;
